    int32_t ReadStockTraceInt(AActor* actor, int32_t offset)
    {
        if (!actor || offset < 0)
            return -1;
        int32_t* value = reinterpret_cast<int32_t*>(
            reinterpret_cast<uintptr_t>(actor) + offset);
        return Memory::IsReadable(value, sizeof(int32_t)) ? *value : -1;
    }

    int32_t ReadStockTraceByte(AActor* actor, int32_t offset)
    {
        if (!actor || offset < 0)
            return -1;
        uint8_t* value = reinterpret_cast<uint8_t*>(
            reinterpret_cast<uintptr_t>(actor) + offset);
        return Memory::IsReadable(value, 1) ? *value : -1;
    }

    std::string ReadStockTraceObject(AActor* actor, int32_t offset)
    {
        if (!actor || offset < 0)
            return "unavailable";
        UObject** field = reinterpret_cast<UObject**>(
            reinterpret_cast<uintptr_t>(actor) + offset);
        if (!Memory::IsReadable(field, sizeof(UObject*)) || !*field ||
            !Memory::IsReadable(*field, sizeof(UObject)))
            return "none";
        return JasonAISafeName(*field);
    }

    void TickStockKillStateTrace(ULONGLONG now)
    {
        if (now < g_StockNextKillStateTraceAt ||
            now >= g_StockKillStateTraceUntil)
            return;
        g_StockNextKillStateTraceAt = now + 1000;
        AActor* counselor = reinterpret_cast<AActor*>(
            Engine::GetSCCharacter());
        AActor* jason = g_JasonAIState.Jason;
        if (!counselor || !jason ||
            !Memory::IsReadable(counselor, sizeof(UObject)) ||
            !Memory::IsReadable(jason, sizeof(UObject)))
            return;
        const std::string state =
            "sweater=" + std::to_string(ReadStockTraceByte(
                counselor, g_StockSweaterFlagOffset)) +
            " wearing=" + std::to_string(ReadStockTraceByte(
                counselor, g_StockWearingSweaterOffset)) +
            " wearingAlt=" + std::to_string(ReadStockTraceByte(
                counselor, g_StockWearingSweaterAltOffset)) +
            " sweaterAbility=" + ReadStockTraceObject(
                counselor, g_StockSweaterAbilityOffset) +
            " activeAbility=" + ReadStockTraceObject(
                counselor, g_StockActiveAbilityOffset) +
            " jasonMask=" + std::to_string(ReadStockTraceByte(
                jason, g_StockMaskOnOffset)) +
            " jasonStun=" + std::to_string(ReadStockTraceByte(
                jason, g_StockJasonStunOffset)) +
            " jasonHealth=" + std::to_string(ReadStockTraceFloat(
                jason, g_StockJasonHealthOffset)) +
            "/" + std::to_string(ReadStockTraceFloat(
                jason, g_StockJasonMaxHealthOffset)) +
            " damageable=" + std::to_string(jason->bCanBeDamaged ? 1 : 0) +
            " damagedCount=" + std::to_string(ReadStockTraceInt(
                jason, g_StockJasonDamageCountOffset)) +
            " maskHitThreshold=" + std::to_string(ReadStockTraceInt(
                jason, g_StockJasonMaskHitThresholdOffset)) +
            " maskThreshold=" + std::to_string(ReadStockTraceFloat(
                jason, g_StockJasonMaskThresholdOffset)) +
            " knockedMaskCount=" + std::to_string(ReadStockTraceInt(
                jason, g_StockJasonKnockedMaskCountOffset)) +
            " attackMod=" + std::to_string(ReadStockTraceFloat(
                counselor, g_StockCounselorAttackOffset +
                    (g_StockCounselorAttackOffset < 0 ? 0 : 4))) +
            " stunMod=" + std::to_string(ReadStockTraceFloat(
                counselor, g_StockCounselorStunOffset +
                    (g_StockCounselorStunOffset < 0 ? 0 : 4))) +
            " damageCharacter=" + std::to_string(ReadStockTraceFloat(
                counselor, g_StockCounselorDamageCharacterOffset)) +
            " weaponDamage=" + std::to_string(ReadStockTraceFloat(
                counselor, g_StockCounselorWeaponDamageOffset));
        if (state != g_StockLastKillState)
        {
            g_StockLastKillState = state;
            Logger::Debug("STOCK KILL STATE: " + state);
        }
    }

    void EnableStockJasonRunSpeed(AActor* jason, ULONGLONG now)
    {
        if (now < g_StockNextRunSpeedCheckAt || !jason ||
            !Memory::IsReadable(jason, sizeof(ACharacter)))
            return;
        g_StockNextRunSpeedCheckAt = now + 30000;
        void* component = reinterpret_cast<ACharacter*>(jason)->CharacterMovement;
        if (!component || !Memory::IsReadable(
                component, sizeof(UCharacterMovementComponent)))
            return;
        auto* move = reinterpret_cast<UCharacterMovementComponent*>(component);
        const float walk = move->MaxWalkSpeed;
        const float run = move->MaxRunSpeed;
        if (!std::isfinite(walk) || !std::isfinite(run) ||
            walk < 25.0f || walk > 2000.0f ||
            run < walk || run > 2500.0f)
            return;
        // Use this Jason variant's own run-speed stat for nav pursuit. A
        // non-running Jason whose run speed equals walk remains unchanged.
        if (run > walk + 10.0f)
            move->MaxWalkSpeed = run;
        if (!g_StockRunSpeedLogged)
        {
            g_StockRunSpeedLogged = true;
            Logger::Debug("STOCK JASON RUN: walk=" +
                std::to_string(walk) + " run=" +
                std::to_string(run) + " applied=" +
                std::string(run > walk + 10.0f ? "true" : "false"));
        }
    }

    AActor* SelectStockPursuitTarget(AActor* jason, ULONGLONG now)
    {
        // The frozen AI's nearest-target scan already rejects blocked and
        // controller-less counselors. Retain its current live target unless
        // another counselor is substantially closer, avoiding a new path
        // request to a different bot on every chase sample.
        AActor* nearest = FindNearestJasonAICounselorTarget(jason);
        if (!nearest)
        {
            g_StockPursuitTarget = nullptr;
            g_StockTargetLastSampleAt = 0;
            return nullptr;
        }
        FVector jasonLocation{};
        FVector nearestLocation{};
        if (!GetJasonAIActorLocation(jason, jasonLocation) ||
            !GetJasonAIActorLocation(nearest, nearestLocation))
            return nearest;
        bool retainedLive = false;
        for (int32_t i = 0; i < g_JasonAITargetCount; ++i)
        {
            if (g_JasonAITargets[i] == g_StockPursuitTarget &&
                !IsJasonAITargetBlocked(g_StockPursuitTarget, now) &&
                Memory::IsReadable(g_StockPursuitTarget, sizeof(UObject)))
            {
                UObject** controllerField = reinterpret_cast<UObject**>(
                    reinterpret_cast<uintptr_t>(g_StockPursuitTarget) + 0x3A0);
                retainedLive = Memory::IsReadable(controllerField,
                    sizeof(UObject*)) && *controllerField &&
                    Memory::IsReadable(*controllerField, sizeof(UObject));
                break;
            }
        }
        FVector retainedLocation{};
        if (retainedLive && g_StockPursuitTarget != nearest &&
            now < g_StockTargetLockUntil &&
            GetJasonAIActorLocation(g_StockPursuitTarget, retainedLocation))
        {
            const float nearestDx = nearestLocation.X - jasonLocation.X;
            const float nearestDy = nearestLocation.Y - jasonLocation.Y;
            const float retainedDx = retainedLocation.X - jasonLocation.X;
            const float retainedDy = retainedLocation.Y - jasonLocation.Y;
            const float nearestDistance = nearestDx * nearestDx +
                nearestDy * nearestDy;
            const float retainedDistance = retainedDx * retainedDx +
                retainedDy * retainedDy;
            if (std::isfinite(nearestDistance) &&
                std::isfinite(retainedDistance) &&
                nearestDistance >= retainedDistance * 0.45f)
                return g_StockPursuitTarget;
        }
        if (g_StockPursuitTarget != nearest)
        {
            g_StockPursuitTarget = nearest;
            g_StockTargetLastSampleAt = 0;
            g_StockTargetLockUntil = now + 6000;
            Logger::Debug("STOCK JASON AI: pursuit target=" +
                JasonAISafeName(reinterpret_cast<UObject*>(nearest)));
        }
        return nearest;
    }

    int32_t LogStockCounselorProperty(AActor* counselor,
        const char* name, bool numeric)
    {
        if (!counselor || !counselor->Class)
            return -1;
        UPropertyLite* property = FindPropertyInHierarchyByName(
            counselor->Class, name);
        if (!property || property->Offset_Internal <= 0 ||
            property->Offset_Internal >= 0x10000 ||
            property->ArrayDim != 1)
        {
            Logger::Debug(std::string("STOCK LAYOUT: ") + name +
                " unavailable");
            return -1;
        }
        const std::string type = JasonAISafeName(
            reinterpret_cast<UObject*>(property->ClassPrivate));
        Logger::Debug(std::string("STOCK LAYOUT: ") + name +
            " type=" + type + " offset=" +
            std::to_string(property->Offset_Internal) +
            " size=" + std::to_string(property->ElementSize));
        if (!numeric)
            return property->Offset_Internal;
        if (
            ((type != "FloatProperty" && type != "StructProperty") ||
                property->ElementSize < 4))
            return -1;
        return property->Offset_Internal;
    }

    float ReadStockTraceFloat(AActor* counselor, int32_t offset)
    {
        if (!counselor || offset < 0)
            return -1.0f;
        float* value = reinterpret_cast<float*>(
            reinterpret_cast<uintptr_t>(counselor) + offset);
        if (!Memory::IsReadable(value, sizeof(float)) ||
            !std::isfinite(*value))
            return -1.0f;
        return *value;
    }

