static void EnableAdditionalJasonAuthoredRunSpeed(
    AdditionalCombatJasonState& state,
    ULONGLONG now)
{
    if (now < state.NextRunSpeedCheckAt || !state.Jason ||
        !Memory::IsReadable(state.Jason, sizeof(ACharacter)))
        return;
    state.NextRunSpeedCheckAt = now + 30000;
    void* movement = reinterpret_cast<ACharacter*>(
        state.Jason)->CharacterMovement;
    if (!movement || !Memory::IsReadable(
            movement, sizeof(UCharacterMovementComponent)))
        return;
    auto* move = reinterpret_cast<UCharacterMovementComponent*>(movement);
    if (!std::isfinite(move->MaxWalkSpeed) ||
        !std::isfinite(move->MaxRunSpeed) ||
        move->MaxWalkSpeed <= 25.0f ||
        move->MaxRunSpeed <= move->MaxWalkSpeed + 25.0f ||
        move->MaxRunSpeed >= 1500.0f)
        return;
    move->MaxWalkSpeed = move->MaxRunSpeed;
    Logger::Debug("F1 additional Jason: authored run speed enabled");
}

