// These three SCDoor bools are mapped from the supported stock EXE's reflected
// IsOpen/IsLocked/IsDestroyed thunks. Check the mapping before reading them.
static bool HaveVerifiedStockDoorState()
{
    static const bool verified = []()
    {
        const uintptr_t image = reinterpret_cast<uintptr_t>(GetModuleHandle(nullptr));
        const uint8_t open[] = {0x0F,0xB6,0x81,0x38,0x05,0,0,0x41,0x88,0,0xC3};
        const uint8_t locked[] = {0x0F,0xB6,0x81,0x39,0x05,0,0,0x41,0x88,0,0xC3};
        const uint8_t destroyed[] = {0x0F,0xB6,0x81,0x3A,0x05,0,0,0x41,0x88,0,0xC3};
        auto match = [image](uintptr_t rva, const uint8_t* bytes, size_t size)
        {
            const void* at = reinterpret_cast<void*>(image + rva);
            return image && Memory::IsReadable(at, size) &&
                std::memcmp(at, bytes, size) == 0;
        };
        return match(0x004A7365, open, sizeof(open)) &&
            match(0x00487C95, locked, sizeof(locked)) &&
            match(0x00487A25, destroyed, sizeof(destroyed));
    }();
    return verified;
}

static __declspec(noinline) bool CanStartEarlyDoorAction(AActor* jason)
{
    if (!jason || !Memory::IsReadable(jason, 0x14D8)) return false;
    const auto* bytes = reinterpret_cast<const uint8_t*>(jason);
    if (bytes[0xE98] || bytes[0xEE8] || bytes[StockPortMap::JasonMorphActive] ||
        bytes[StockPortMap::JasonShiftActive] ||
        *reinterpret_cast<AActor* const*>(bytes + StockPortMap::JasonActiveHeldActor))
        return false;
    const uintptr_t image = reinterpret_cast<uintptr_t>(GetModuleHandle(nullptr));
    const uintptr_t stun = image + StockPortMap::IsJasonStunned;
    if (!image || !Memory::IsReadable(reinterpret_cast<void*>(stun), 1)) return false;
    __try
    {
        return !reinterpret_cast<bool(__fastcall*)(AActor*)>(stun)(jason) &&
            !IsJasonInNativeSpecialMove(jason);
    }
    __except (EXCEPTION_EXECUTE_HANDLER) { return false; }
}

static AActor* FindSelectedClosedDoorOnApproach(AActor* jason,
    const FVector& jasonAt, const FVector& targetAt, FVector& doorAt)
{
    if (!jason || !HaveVerifiedStockDoorState()) return nullptr;
    auto** managerAt = reinterpret_cast<UObject**>(reinterpret_cast<uintptr_t>(jason) + 0xE18);
    if (!Memory::IsReadable(managerAt, sizeof(UObject*)) || !*managerAt) return nullptr;
    const uintptr_t manager = reinterpret_cast<uintptr_t>(*managerAt);
    if (!Memory::IsReadable(reinterpret_cast<void*>(manager + 0x210), 0x28)) return nullptr;
    UObject* selected = *reinterpret_cast<UObject**>(manager + 0x230);
    if (!selected) selected = *reinterpret_cast<UObject**>(manager + 0x210);
    if (!selected || !Memory::IsReadable(selected, 0x451) ||
        !reinterpret_cast<uint8_t*>(selected)[0x450]) return nullptr;
    AActor* door = *reinterpret_cast<AActor**>(reinterpret_cast<uintptr_t>(selected) + 0xE0);
    if (!door || !Memory::IsReadable(door, 0x560) || !door->Class) return nullptr;
    bool isDoor = false;
    int depth = 0;
    for (UStruct* type = reinterpret_cast<UStruct*>(door->Class);
         type && depth++ < 16 && Memory::IsReadable(type, sizeof(UStruct));
         type = SafeReadSuperStruct(type))
    {
        if (FastRawObjectNameEquals(reinterpret_cast<UObject*>(type), "SCDoor"))
        { isDoor = true; break; }
    }
    if (!isDoor) return nullptr;
    const auto* bytes = reinterpret_cast<const uint8_t*>(door);
    if (bytes[0x538] != 0 || bytes[0x53A] != 0 || bytes[0x539] > 1 ||
        *reinterpret_cast<void* const*>(bytes + 0x558)) return nullptr;
    // Same selected-component world position used by native JasonInteraction.
    doorAt = *reinterpret_cast<FVector*>(reinterpret_cast<uintptr_t>(selected) + 0x190);
    if (!JasonDoorApproachPolicy::IsOnApproach(
            doorAt.X - jasonAt.X, doorAt.Y - jasonAt.Y, doorAt.Z - jasonAt.Z,
            targetAt.X - jasonAt.X, targetAt.Y - jasonAt.Y, targetAt.Z - jasonAt.Z))
        return nullptr;
    return CanStartEarlyDoorAction(jason) ? door : nullptr;
}

static bool TryAdditionalJasonNativeDoor(
    AdditionalCombatJasonState& state,
    AActor* target,
    const FVector& jasonLocation,
    const FVector& targetLocation,
    ULONGLONG now,
    bool earlyProbe = false)
{
    auto& doorState = state.Door;
    if (now < doorState.NextAttemptAt) return false;
    FVector earlyDoorAt{};
    AActor* earlyDoor = earlyProbe ? FindSelectedClosedDoorOnApproach(
        state.Jason, jasonLocation, targetLocation, earlyDoorAt) : nullptr;
    if (earlyProbe && !earlyDoor) return false;
    if (doorState.SampleTarget != target)
    {
        doorState.SampleTarget = target;
        doorState.HasSample = false;
        doorState.BlockedSamples = 0;
    }
    const float targetX = targetLocation.X - jasonLocation.X;
    const float targetY = targetLocation.Y - jasonLocation.Y;
    if (doorState.HasSample &&
        targetX * targetX + targetY * targetY > 100.0f * 100.0f)
    {
        const float movedX = jasonLocation.X -
            doorState.LastJasonLocation.X;
        const float movedY = jasonLocation.Y -
            doorState.LastJasonLocation.Y;
        doorState.BlockedSamples =
            movedX * movedX + movedY * movedY < 80.0f * 80.0f
                ? static_cast<uint8_t>((std::min)(
                    int(doorState.BlockedSamples) + 1, 3))
                : 0;
    }
    else
        doorState.BlockedSamples = 0;
    doorState.LastJasonLocation = jasonLocation;
    doorState.HasSample = true;
    if (!earlyProbe && doorState.BlockedSamples < 2)
        return false;

    UObject** managerField = reinterpret_cast<UObject**>(
        reinterpret_cast<uintptr_t>(state.Jason) + 0xE18);
    if (!Memory::IsReadable(managerField, sizeof(UObject*)) ||
        !*managerField ||
        !Memory::IsReadable(*managerField, sizeof(UObject)))
        return false;
    UObject* manager = *managerField;
    UObject** bestField = reinterpret_cast<UObject**>(
        reinterpret_cast<uintptr_t>(manager) + 0x230);
    UObject** fallbackField = reinterpret_cast<UObject**>(
        reinterpret_cast<uintptr_t>(manager) + 0x210);
    UObject* interactable = Memory::IsReadable(
        bestField, sizeof(UObject*)) ? *bestField : nullptr;
    if (!interactable && Memory::IsReadable(
            fallbackField, sizeof(UObject*)))
        interactable = *fallbackField;
    if (!interactable ||
        !Memory::IsReadable(interactable, sizeof(UObject)))
        return false;
    AActor** ownerField = reinterpret_cast<AActor**>(
        reinterpret_cast<uintptr_t>(interactable) + 0xE0);
    if (!Memory::IsReadable(ownerField, sizeof(AActor*)) ||
        !*ownerField ||
        !Memory::IsReadable(*ownerField, sizeof(UObject)) ||
        !(*ownerField)->Class)
        return false;
    AActor* door = *ownerField;
    if (earlyProbe && door != earlyDoor) return false;
    bool isDoor = false;
    int depth = 0;
    for (UStruct* current = reinterpret_cast<UStruct*>(door->Class);
         current && depth++ < 16 &&
             Memory::IsReadable(current, sizeof(UStruct));
         current = SafeReadSuperStruct(current))
    {
        if (FastRawObjectNameEquals(
                reinterpret_cast<UObject*>(current), "SCDoor"))
        {
            isDoor = true;
            break;
        }
    }
    if (!isDoor ||
        (!earlyProbe && door == doorState.LastDoorInteracted &&
            now < doorState.SameDoorRetryAt))
        return false;
    FVector doorLocation{};
    if (!GetJasonAIActorLocation(door, doorLocation))
        return false;
    const float doorX = doorLocation.X - jasonLocation.X;
    const float doorY = doorLocation.Y - jasonLocation.Y;
    const float doorZ = doorLocation.Z - jasonLocation.Z;
    if (doorX * doorX + doorY * doorY + doorZ * doorZ >
        500.0f * 500.0f)
        return false;

    HMODULE module = GetModuleHandle(nullptr);
    const uintptr_t address = module
        ? reinterpret_cast<uintptr_t>(module) +
            StockPortMap::JasonInteraction
        : 0;
    const uint8_t signature[] = {
        0x48, 0x89, 0x5C, 0x24, 0x20, 0x55, 0x48, 0x8B,
        0xEC, 0x48, 0x81, 0xEC, 0x80, 0x00, 0x00, 0x00
    };
    if (!address || !Memory::IsReadable(
            reinterpret_cast<void*>(address), sizeof(signature)) ||
        std::memcmp(reinterpret_cast<void*>(address), signature,
            sizeof(signature)) != 0)
        return false;
    doorState.NextAttemptAt = now + (earlyProbe ? 2000 : 8000);
    if (earlyProbe && !FaceJasonAtLocationOnGameThread(
            state.Jason, state.Controller, earlyDoorAt)) return false;
    auto** oldBreakTarget = reinterpret_cast<AActor**>(
        reinterpret_cast<uintptr_t>(state.Jason) + StockPortMap::JasonDoorBreakTarget);
    if (earlyProbe && Memory::IsReadable(oldBreakTarget, sizeof(AActor*)) &&
        *oldBreakTarget == door) *oldBreakTarget = nullptr;
    if (!SafeJasonInteractionCall(state.Jason, address))
        return false;
    doorState.BlockedSamples = 0;
    doorState.LastDoorInteracted = door;
    AActor** breakTargetField = reinterpret_cast<AActor**>(
        reinterpret_cast<uintptr_t>(state.Jason) +
            StockPortMap::JasonDoorBreakTarget);
    const bool breakStarted = Memory::IsReadable(
        breakTargetField, sizeof(AActor*)) && *breakTargetField == door;
    const bool openObserved = earlyProbe &&
        reinterpret_cast<uint8_t*>(door)[0x538] != 0;
    // Dispatch is not proof of an open. Allow a short, bounded retry if the
    // native animation has not published an open or breakdown state yet.
    doorState.SameDoorRetryAt = now + (earlyProbe && !breakStarted && !openObserved ? 2000 : 30000);
    if (earlyProbe && !breakStarted && !openObserved) doorState.NextAttemptAt = now + 2000;
    doorState.InteractionUntil = now + (breakStarted ? 6500 : 2500);
    Logger::Debug(std::string("F1 additional Jason: native door ") +
        (breakStarted ? "break" : (earlyProbe && !openObserved ? "open requested" : "open")) + " | door=" +
        JasonAISafeName(reinterpret_cast<UObject*>(door)));
    return true;
}


static int32_t g_TrapTeleportExemptionDepth = 0;
static UFunction* g_MinimumMorphTeleportFunction = nullptr;
static ULONGLONG g_NextMinimumMorphLogAt = 0;
static ULONGLONG g_NextMorphCooldownRefusalLogAt = 0;

// Observe only the frozen primary's ordinary stock chase requests. Reuse its
// existing target/retry state, which is reset by its world/match lifecycle.
// Never request a path here or release the existing nav-request cadence lock.
static void ObserveStockChaseMoveResult(
    void* obj, void* func, void* params, bool callOK)
{
    if (!callOK || g_HostedOnlineBridge || !g_JasonAIState.Active ||
        obj != g_JasonAIState.Controller || !func || !params ||
        g_JasonAIState.StartupTrapSetupActive ||
        g_JasonAIState.StartupTrapPhoneApproachActive ||
        g_JasonAIState.DoorBreakActive || g_JasonAIState.KnifeSequenceActive ||
        g_JasonAIState.AttackPressed || g_JasonAIState.GrabKillReadyAt != 0 ||
        g_TrapTeleportExemptionDepth != 0 ||
        !FastRawObjectNameEquals(reinterpret_cast<UObject*>(func), "MoveToLocation"))
        return;

    // Same verified 40-byte reflected layout as the frozen stock adapter.
    struct MoveParams
    {
        FVector Dest;
        float AcceptanceRadius;
        bool StopOnOverlap;
        bool UsePathfinding;
        bool ProjectToNavigation;
        bool CanStrafe;
        uint8_t Padding0[4];
        UClass* FilterClass;
        bool AllowPartialPath;
        uint8_t ReturnValue;
        uint8_t Padding1[6];
    };
    static_assert(sizeof(MoveParams) == 40);
    static_assert(offsetof(MoveParams, ReturnValue) == 33);
    if (!Memory::IsReadable(params, sizeof(MoveParams))) return;
    const auto& move = *reinterpret_cast<const MoveParams*>(params);
    if (move.ReturnValue != 1)
    {
        g_JasonAIState.NoPathTarget = nullptr;
        g_JasonAIState.ConsecutiveNoPathTargets = 0;
        return;
    }

    AActor* target = g_JasonAIState.Target;
    FVector targetAt{}, jasonAt{};
    if (!target || !GetJasonAIActorLocation(target, targetAt) ||
        !GetJasonAIActorLocation(g_JasonAIState.Jason, jasonAt)) return;
    const float goalX = targetAt.X - move.Dest.X;
    const float goalY = targetAt.Y - move.Dest.Y;
    const float goalZ = targetAt.Z - move.Dest.Z;
    const bool matchesTarget = goalX * goalX + goalY * goalY + goalZ * goalZ <= 25.0f * 25.0f;
    const float dx = targetAt.X - jasonAt.X;
    const float dy = targetAt.Y - jasonAt.Y;
    const float dz = targetAt.Z - jasonAt.Z;
    if (!JasonChaseRetryPolicy::IsSuspiciousAlreadyAtGoal(
            move.ReturnValue, dx * dx + dy * dy + dz * dz, matchesTarget))
    {
        g_JasonAIState.NoPathTarget = nullptr;
        g_JasonAIState.ConsecutiveNoPathTargets = 0;
        return;
    }

    g_JasonAIState.ConsecutiveNoPathTargets =
        JasonChaseRetryPolicy::AdvanceRepeatedResult(
            g_JasonAIState.ConsecutiveNoPathTargets,
            g_JasonAIState.NoPathTarget == target);
    g_JasonAIState.NoPathTarget = target;
    if (g_JasonAIState.ConsecutiveNoPathTargets < 2) return;

    // Never remove the only usable target. A short retry window avoids the
    // donor's escalating 90-second/10-minute blacklist for a temporary block.
    const int32_t index = FindJasonAITargetIndex(target);
    if (index >= 0 && HasAlternativeUsableJasonAITarget(target))
    {
        g_JasonAITargetBlockedUntil[index] = GetTickCount64() + 10000;
        g_JasonAIState.Target = nullptr;
        Logger::Debug("Jason AI stock chase: repeated distant AlreadyAtGoal; alternate target at existing nav cadence");
    }
    g_JasonAIState.NoPathTarget = nullptr;
    g_JasonAIState.ConsecutiveNoPathTargets = 0;
}

extern "C" __declspec(noinline) bool FrozenBridgeSafeProcessEventCall(
    uintptr_t vptr,
    void* obj,
    void* func,
    void* params)
{
    AActor* jason = g_JasonAIState.Jason;
    const bool mayBeJasonTeleport =
        g_JasonAIState.Active &&
        jason &&
        obj == jason &&
        func &&
        params &&
        FastRawObjectNameEquals(reinterpret_cast<UObject*>(func), "K2_TeleportTo");
    bool forwardedStuckRecoveryTeleport = false;

    if (mayBeJasonTeleport &&
        Memory::IsReadable(jason, sizeof(UObject)) &&
        jason->Class &&
        Memory::IsReadable(jason->Class, sizeof(UObject)))
    {
        if (!g_MinimumMorphTeleportFunction ||
            !Memory::IsReadable(
                g_MinimumMorphTeleportFunction,
                sizeof(UObject)))
        {
            g_MinimumMorphTeleportFunction =
                FindFunctionInHierarchyByName(
                    jason->Class,
                    "K2_TeleportTo");
        }

        if (func == g_MinimumMorphTeleportFunction)
        {
            const ULONGLONG now = GetTickCount64();
            const ULONGLONG morphReadyAt = JasonAIMorphReadyAt();
            if (morphReadyAt != 0 && now < morphReadyAt)
            {
                // The frozen counselor-ring stuck fallback bypasses the
                // shared Morph timer entirely.  Refuse every ordinary Jason
                // teleport until the same twenty-second cooldown used by
                // startup, distance, and trap-response Morphs has elapsed.
                reinterpret_cast<uint8_t*>(params)[24] = 0;
                if (now >= g_NextMorphCooldownRefusalLogAt)
                {
                    g_NextMorphCooldownRefusalLogAt = now + 2000;
                    Logger::Success(
                        "18L-AI counselor bridge: ordinary/stuck Morph refused by shared cooldown | remainingMs=" +
                        std::to_string(morphReadyAt - now));
                }
                return true;
            }

            // Scripted phone/car setup and owned-trap response are exempt
            // only from the proximity rule.  They still share the same
            // cooldown above.
            const bool ordinaryDistanceGate =
                !g_JasonAIState.StartupTrapSetupActive &&
                g_TrapTeleportExemptionDepth == 0;
            if (!ordinaryDistanceGate)
                return SafeProcessEventCall(vptr, obj, func, params);

            const bool stuckRecovery =
                g_JasonAIState.ConsecutiveStuckChecks >= 2;
            AActor* counselor =
                FindNearestJasonAICounselorTarget(jason);
            FVector jasonLocation{};
            FVector counselorLocation{};
            if (counselor &&
                GetJasonAIActorLocation(jason, jasonLocation) &&
                GetJasonAIActorLocation(counselor, counselorLocation))
            {
                const float dx = counselorLocation.X - jasonLocation.X;
                const float dy = counselorLocation.Y - jasonLocation.Y;
                const float dz = counselorLocation.Z - jasonLocation.Z;
                const float distanceSquared = dx * dx + dy * dy + dz * dz;
                // The donor permits nearby recovery only after two additional
                // confirmed no-movement deferrals. Previously this adapter
                // still refused it inside 30m, contradicting that decision.
                // Keep 10m combat spacing, the Morph cooldown, and all native
                // busy states; no new nav query or per-frame scan is added.
                const bool confirmedLocalRecovery = stuckRecovery &&
                    g_JasonAIState.ConsecutiveNearTargetStuckDeferrals >= 2;
                if (confirmedLocalRecovery && IsJasonBridgeCombatBusy(now, false))
                {
                    reinterpret_cast<uint8_t*>(params)[24] = 0;
                    return true;
                }
                const float minimumMorphDistanceCm =
                    stuckRecovery && !confirmedLocalRecovery ? 3000.0f : 1000.0f;
                if (std::isfinite(distanceSquared) &&
                    distanceSquared <
                        minimumMorphDistanceCm * minimumMorphDistanceCm)
                {
                    // K2_TeleportTo's bool return value is the final byte in
                    // the frozen helper's verified 28-byte parameter block.
                    reinterpret_cast<uint8_t*>(params)[24] = 0;
                    if (now >= g_NextMinimumMorphLogAt)
                    {
                        g_NextMinimumMorphLogAt = now + 2000;
                        Logger::Success(
                            std::string(
                                "18L-AI counselor bridge: ") +
                            (stuckRecovery && !confirmedLocalRecovery
                                ? "stuck-recovery Morph refused inside 30m local-action radius"
                                : "ordinary Morph refused inside 10m walk radius") +
                            " | distanceCm=" +
                            std::to_string(std::sqrt(distanceSquared)));
                    }
                    return true;
                }

                forwardedStuckRecoveryTeleport = stuckRecovery;
            }
        }
    }

    const bool callOK = SafeProcessEventCall(vptr, obj, func, params);
    ObserveStockChaseMoveResult(obj, func, params, callOK);
    if (forwardedStuckRecoveryTeleport &&
        callOK &&
        reinterpret_cast<uint8_t*>(params)[24] != 0)
    {
        // Frozen stuck recovery did not participate in the shared Morph
        // timer. Count its successful counselor-ring jump so it cannot chain
        // another Morph before the normal twenty-second recharge.
        MarkJasonAIMorphTeleportUsed("StuckRecovery");
    }
    return callOK;
}

