    bool ObjectClassDerivesFromExact(UObject* object, const char* className)
    {
        if (!object ||
            !className ||
            !Memory::IsReadable(object, sizeof(UObject)) ||
            !object->Class)
        {
            return false;
        }

        for (UStruct* current = reinterpret_cast<UStruct*>(object->Class);
            current;
            current = SafeReadSuperStruct(current))
        {
            if (!Memory::IsReadable(current, sizeof(UStruct)))
                break;
            if (JasonAISafeName(reinterpret_cast<UObject*>(current)) == className)
                return true;
        }
        return false;
    }

    UField* FindOfflineRecoveryFieldCached(UObject*, const char*, bool);

    UObject* ReadReflectedObjectProperty(UObject* owner, const char* propertyName)
    {
        if (!owner ||
            !propertyName ||
            !Memory::IsReadable(owner, sizeof(UObject)) ||
            !owner->Class)
        {
            return nullptr;
        }

        // The hosted kill-team validates live ownership on a short cadence.
        // Class metadata is immutable within an authoritative Hunt world;
        // resolve each class/field offset once, but still read and validate
        // the *current* object value on every call. The world key prevents
        // stale Blueprint offsets surviving match travel/reload.
        int32_t offset = -1;
        if (g_HostedOnlineBridge && std::strlen(propertyName) < 64)
        {
            struct CachedField { UWorld* World; UClass* Class; char Name[64]; int32_t Offset; };
            static CachedField cache[64]{};
            static uint32_t nextSlot = 0;
            bool found = false;
            for (const CachedField& entry : cache)
                if (entry.World == g_JasonAIState.World && entry.Class == owner->Class &&
                    std::strcmp(entry.Name, propertyName) == 0)
                { offset = entry.Offset; found = true; break; }
            if (!found)
            {
                UPropertyLite* property = FindPropertyInHierarchyByName(owner->Class, propertyName);
                offset = property && property->Offset_Internal > 0 &&
                    property->Offset_Internal < 0x10000 ? property->Offset_Internal : -1;
                CachedField& entry = cache[nextSlot++ % 64];
                entry.World = g_JasonAIState.World;
                entry.Class = owner->Class;
                std::strcpy(entry.Name, propertyName);
                entry.Offset = offset;
            }
        }
        else
        {
            // Offline shares the same immutable metadata optimization; never
            // cache the live pointer value (possession/escape can change it).
            UPropertyLite* property = reinterpret_cast<UPropertyLite*>(
                FindOfflineRecoveryFieldCached(owner, propertyName, false));
            offset = property && property->Offset_Internal > 0 &&
                property->Offset_Internal < 0x10000 ? property->Offset_Internal : -1;
        }
        if (offset < 0) return nullptr;
        UObject** field = reinterpret_cast<UObject**>(
            reinterpret_cast<uintptr_t>(owner) + offset);
        if (!Memory::IsReadable(field, sizeof(UObject*)) ||
            !*field ||
            !Memory::IsReadable(*field, sizeof(UObject)))
        {
            return nullptr;
        }
        return *field;
    }

    static bool BridgeFNameEntryEquals(
        TNameEntryArray* names, int32_t index, const char* wanted)
    {
        // A page query for every name dominated first-use event lookup. The
        // complete speculative dereference and comparison stay SEH-guarded;
        // a readable page alone never guaranteed a live/terminated entry.
        __try
        {
            if (!names || !wanted || !names->IsValidIndex(index) ||
                index / 16384 >= 128)
                return false;
            const FNameEntry* entry = names->GetById(index);
            return entry && std::strcmp(entry->AnsiName, wanted) == 0;
        }
        __except (EXCEPTION_EXECUTE_HANDLER)
        {
            return false;
        }
    }

    static int32_t BridgeFNameCount(TNameEntryArray* names)
    {
        __try
        {
            const int32_t count = names ? names->NumElements : 0;
            return count > 0 && count <= 4000000 ? count : 0;
        }
        __except (EXCEPTION_EXECUTE_HANDLER)
        {
            return 0;
        }
    }

    static bool BridgeFunctionNameEquals(UFunction* function, const char* wanted)
    {
        __try
        {
            return function && BridgeFNameEntryEquals(GNames, function->NameIndex, wanted);
        }
        __except (EXCEPTION_EXECUTE_HANDLER)
        {
            return false;
        }
    }

    struct BridgeExactFNameCache
    {
        struct Entry
        {
            char Name[128]{};
            int32_t Index = -1;
        };
        TNameEntryArray* Names = nullptr;
        int32_t HighCount = 0;
        size_t Next = 0;
        Entry Entries[64]{};
    };

    int32_t FindFNameIndexExact(const char* wanted)
    {
        TNameEntryArray* names = GNames;
        if (!wanted || !names ||
            !Memory::IsReadable(names, sizeof(TNameEntryArray)))
            return -1;
        const int32_t count = BridgeFNameCount(names);
        if (count == 0)
            return -1;

        // Share successful resolutions between observers on this thread;
        // no locks, allocations, eager name-table build, or negative entries.
        // GNames is append-only during ordinary play, but invalidate on table
        // replacement/shrink and recheck the exact entry on every cache hit.
        static thread_local BridgeExactFNameCache cache;
        if (cache.Names != names || count < cache.HighCount)
        {
            for (auto& entry : cache.Entries)
                entry.Index = -1;
            cache.Names = names;
            cache.Next = 0;
        }
        cache.HighCount = count;
        for (auto& entry : cache.Entries)
        {
            if (entry.Index < 0 || std::strcmp(entry.Name, wanted) != 0)
                continue;
            if (BridgeFNameEntryEquals(names, entry.Index, wanted))
                return entry.Index;
            entry.Index = -1;
        }

        // Preserve synchronous, ascending exact-name resolution. Never
        // return a temporary miss due to a scan budget: legacy callers can
        // retain -1, so only an actual complete miss may return -1 here.
        for (int32_t index = 0; index < BridgeFNameCount(names); ++index)
        {
            if (!BridgeFNameEntryEquals(names, index, wanted))
                continue;
            const size_t length = std::strlen(wanted);
            if (length < sizeof(cache.Entries[0].Name))
            {
                auto& entry = cache.Entries[cache.Next];
                std::memcpy(entry.Name, wanted, length + 1);
                entry.Index = index;
                cache.Next = (cache.Next + 1) % 64;
            }
            return index;
        }
        return -1;
    }

    void ResolveCounselorBlackboardNameIndices()
    {
        if (g_CounselorBlackboardNameResolutionComplete ||
            (g_SCWeaponNameIndex >= 0 &&
            g_ShouldFleeKillerNameIndex >= 0 &&
            g_ShouldFightBackNameIndex >= 0 &&
            g_ShouldArmedFightBackNameIndex >= 0 &&
            g_ShouldMeleeFightBackNameIndex >= 0 &&
            g_SeekWeaponWhileFleeingNameIndex >= 0 &&
            g_ShouldHideNameIndex >= 0 &&
            g_ShouldOrientTowardKillerNameIndex >= 0 &&
            g_JasonCharacterNameIndex >= 0))
        {
            g_CounselorBlackboardNameResolutionComplete = true;
            return;
        }

        if (!GNames ||
            !Memory::IsReadable(GNames, sizeof(TNameEntryArray)) ||
            GNames->NumElements <= 0 ||
            GNames->NumElements > 4000000)
        {
            return;
        }

        // Never scan the complete multi-million-entry name table on a game
        // frame. Advance a very small bounded chunk and stop permanently after
        // the keys or current table end. The caller schedules incomplete
        // discovery frequently so this finishes without a visible burst.
        constexpr int32_t NamesPerMaintenancePass = 128;
        const int32_t end = (std::min)(
            GNames->NumElements,
            g_CounselorBlackboardNameResolveCursor +
                NamesPerMaintenancePass);
        for (int32_t index = g_CounselorBlackboardNameResolveCursor;
             index < end;
             ++index)
        {
            const char* name = nullptr;
            if (!TryReadBridgeFName(index, &name))
                continue;
            if (g_SCWeaponNameIndex < 0 &&
                std::strcmp(name, "SCWeapon") == 0)
                g_SCWeaponNameIndex = index;
            else if (g_ShouldFleeKillerNameIndex < 0 &&
                std::strcmp(name, "ShouldFleeKiller") == 0)
                g_ShouldFleeKillerNameIndex = index;
            else if (g_ShouldFightBackNameIndex < 0 &&
                std::strcmp(name, "ShouldFightBack") == 0)
                g_ShouldFightBackNameIndex = index;
            else if (g_ShouldArmedFightBackNameIndex < 0 &&
                std::strcmp(name, "ShouldArmedFightBack") == 0)
                g_ShouldArmedFightBackNameIndex = index;
            else if (g_ShouldMeleeFightBackNameIndex < 0 &&
                std::strcmp(name, "ShouldMeleeFightBack") == 0)
                g_ShouldMeleeFightBackNameIndex = index;
            else if (g_SeekWeaponWhileFleeingNameIndex < 0 &&
                std::strcmp(name, "SeekWeaponWhileFleeing") == 0)
                g_SeekWeaponWhileFleeingNameIndex = index;
            else if (g_ShouldHideNameIndex < 0 &&
                std::strcmp(name, "ShouldHide") == 0)
                g_ShouldHideNameIndex = index;
            else if (g_ShouldOrientTowardKillerNameIndex < 0 &&
                std::strcmp(name, "ShouldOrientTowardKiller") == 0)
                g_ShouldOrientTowardKillerNameIndex = index;
            else if (g_JasonCharacterNameIndex < 0 &&
                std::strcmp(name, "JasonCharacter") == 0)
                g_JasonCharacterNameIndex = index;

            if (g_SCWeaponNameIndex >= 0 &&
                g_ShouldFleeKillerNameIndex >= 0 &&
                g_ShouldFightBackNameIndex >= 0 &&
                g_ShouldArmedFightBackNameIndex >= 0 &&
                g_ShouldMeleeFightBackNameIndex >= 0 &&
                g_SeekWeaponWhileFleeingNameIndex >= 0 &&
                g_ShouldHideNameIndex >= 0 &&
                g_ShouldOrientTowardKillerNameIndex >= 0 &&
                g_JasonCharacterNameIndex >= 0)
            {
                g_CounselorBlackboardNameResolveCursor = index + 1;
                g_CounselorBlackboardNameResolutionComplete = true;
                break;
            }
        }
        g_CounselorBlackboardNameResolveCursor = end;
        if (end >= GNames->NumElements)
            g_CounselorBlackboardNameResolutionComplete = true;
    }

    bool SetBlackboardBool(UObject* blackboard, int32_t keyIndex, bool value)
    {
        if (!blackboard ||
            keyIndex < 0 ||
            !Memory::IsReadable(blackboard, sizeof(UObject)) ||
            !blackboard->Class)
        {
            return false;
        }

        // All counselor blackboards share a class. Cache both successful and
        // failed reflection lookups so the one-second kill-team path never
        // re-walks the UFunction hierarchy.
        static UClass* cachedClass = nullptr;
        static UFunction* cachedFunction = nullptr;
        if (cachedClass != blackboard->Class)
        {
            cachedClass = blackboard->Class;
            cachedFunction = FindFunctionInHierarchyByName(
                blackboard->Class,
                "SetValueAsBool");
        }
        UFunction* function = cachedFunction;
        if (!function)
            return false;

        struct Params
        {
            FName KeyName;
            bool BoolValue;
            uint8_t Padding[3];
        };
        Params params{};
        params.KeyName = FName(keyIndex, 0);
        params.BoolValue = value;
        return SafeProcessEventCall(
            reinterpret_cast<uintptr_t>(blackboard),
            blackboard,
            function,
            &params);
    }

    bool SetBlackboardObject(
        UObject* blackboard,
        int32_t keyIndex,
        UObject* value)
    {
        if (!blackboard ||
            keyIndex < 0 ||
            !value ||
            !Memory::IsReadable(blackboard, sizeof(UObject)) ||
            !blackboard->Class ||
            !Memory::IsReadable(value, sizeof(UObject)))
        {
            return false;
        }

        static UClass* cachedClass = nullptr;
        static UFunction* cachedFunction = nullptr;
        if (cachedClass != blackboard->Class)
        {
            cachedClass = blackboard->Class;
            cachedFunction = FindFunctionInHierarchyByName(
                blackboard->Class,
                "SetValueAsObject");
        }
        UFunction* function = cachedFunction;
        if (!function)
            return false;

        struct Params
        {
            FName KeyName;
            UObject* ObjectValue;
        };
        Params params{};
        params.KeyName = FName(keyIndex, 0);
        params.ObjectValue = value;
        return SafeProcessEventCall(
            reinterpret_cast<uintptr_t>(blackboard),
            blackboard,
            function,
            &params);
    }

    UObject* GetBlackboardObject(UObject* blackboard, int32_t keyIndex)
    {
        if (!blackboard ||
            keyIndex < 0 ||
            !Memory::IsReadable(blackboard, sizeof(UObject)) ||
            !blackboard->Class)
        {
            return nullptr;
        }

        static UClass* cachedClass = nullptr;
        static UFunction* cachedFunction = nullptr;
        if (cachedClass != blackboard->Class)
        {
            cachedClass = blackboard->Class;
            cachedFunction = FindFunctionInHierarchyByName(
                blackboard->Class,
                "GetValueAsObject");
        }
        UFunction* function = cachedFunction;
        if (!function)
            return nullptr;

        struct Params
        {
            FName KeyName;
            UObject* ReturnValue;
        };
        Params params{};
        params.KeyName = FName(keyIndex, 0);
        if (!SafeProcessEventCall(
                reinterpret_cast<uintptr_t>(blackboard),
                blackboard,
                function,
                &params))
        {
            return nullptr;
        }
        return params.ReturnValue &&
            Memory::IsReadable(params.ReturnValue, sizeof(UObject))
                ? params.ReturnValue
                : nullptr;
    }

    enum class CounselorRouteMatchPhase : uint8_t
    {
        Unknown,
        InProgress,
        NotInProgress
    };

    CounselorRouteMatchPhase ReadCounselorRouteMatchPhase()
    {
        UWorld* world = g_HostedOnlineBridge ? g_JasonAIState.World : Engine::GetWorld();
        if (!world ||
            world != g_JasonAIState.World ||
            !Memory::IsReadable(world, sizeof(UWorld)))
        {
            return CounselorRouteMatchPhase::NotInProgress;
        }

        AActor* gameState = ReadActorField(
            reinterpret_cast<UObject*>(world),
            0xF8);
        if (!gameState ||
            !Memory::IsReadable(gameState, sizeof(UObject)) ||
            !gameState->Class ||
            !Memory::IsReadable(gameState->Class, sizeof(UClass)))
        {
            return CounselorRouteMatchPhase::Unknown;
        }

        if (g_MatchStateOffset < 0)
        {
            UPropertyLite* property =
                FindPropertyInHierarchyByName(
                    gameState->Class,
                    "MatchState");
            if (!property ||
                property->Offset_Internal <= 0 ||
                property->Offset_Internal >= 0x10000 ||
                property->ElementSize != sizeof(FName))
            {
                return CounselorRouteMatchPhase::Unknown;
            }
            g_MatchStateOffset = property->Offset_Internal;
        }

        const FName* matchState = reinterpret_cast<const FName*>(
            reinterpret_cast<uintptr_t>(gameState) + g_MatchStateOffset);
        if (!Memory::IsReadable(matchState, sizeof(FName)) ||
            !GNames ||
            !GNames->IsValidIndex(matchState->ComparisonIndex))
        {
            return CounselorRouteMatchPhase::Unknown;
        }

        const FNameEntry* entry =
            GNames->GetById(matchState->ComparisonIndex);
        if (!entry || !Memory::IsReadable(entry, 0x20))
            return CounselorRouteMatchPhase::Unknown;

        return std::strcmp(entry->AnsiName, "InProgress") == 0
            ? CounselorRouteMatchPhase::InProgress
            : CounselorRouteMatchPhase::NotInProgress;
    }

    bool IsHostedAuthorityWorld()
    {
        if (!g_HostedOnlineBridge || !g_JasonAIState.Active ||
            !g_JasonAIState.World || Engine::GetWorld() != g_JasonAIState.World)
            return false;
        UObject* mode = g_HostedAuthorityMode;
        return mode && Memory::IsReadable(mode, 0x111) &&
            mode->Class == g_HostedAuthorityClass &&
            ReadActorField(reinterpret_cast<UObject*>(g_JasonAIState.World), 0xF0) == mode &&
            *reinterpret_cast<const uint8_t*>(reinterpret_cast<uintptr_t>(mode) + 0x110) == 3;
    }

    bool HostedObjectBelongsToWorld(UObject* object)
    {
        for (int depth = 0; object && depth < 8; ++depth)
        {
            if (!Memory::IsReadable(object, sizeof(UObject))) return false;
            if (object == reinterpret_cast<UObject*>(g_JasonAIState.World)) return true;
            object = object->OuterPrivate;
        }
        return false;
    }

    void FinishRoadMorphTrace(const char* reason)
    {
        if (g_RoadMorphTraceCar && !g_RoadMorphTraceReported)
        {
            Logger::Debug(
                "18L-BV road Morph path trace ended | reason=" +
                std::string(reason ? reason : "unknown") +
                " | segments=" + std::to_string(g_RoadMorphTraceSegments) +
                " | nearestCarPathCm=" +
                (g_RoadMorphTraceSegments > 0
                    ? std::to_string(g_RoadMorphTraceBestDistance)
                    : "unobserved") +
                " | signedLateralCm=" +
                (g_RoadMorphTraceSegments > 0
                    ? std::to_string(g_RoadMorphTraceSignedOffset)
                    : "unobserved"));
        }
        g_RoadMorphTraceCar = nullptr;
        g_RoadMorphTraceLanding = FVector{};
        g_RoadMorphTracePreviousCar = FVector{};
        g_RoadMorphTraceStartedAt = 0;
        g_RoadMorphTraceBestDistance = FLT_MAX;
        g_RoadMorphTraceSignedOffset = 0.0f;
        g_RoadMorphTraceSegments = 0;
        g_RoadMorphTraceHavePrevious = false;
        g_RoadMorphTraceReported = false;
    }

    void BeginRoadMorphTrace(
        AActor* car,
        const FVector& carLocation,
        const FVector& landing,
        const FVector& travelDirection,
        ULONGLONG now)
    {
        FinishRoadMorphTrace("new-Morph");
        g_RoadMorphTraceCar = car;
        g_RoadMorphTraceLanding = landing;
        g_RoadMorphTracePreviousCar = carLocation;
        g_RoadMorphTraceStartedAt = now;
        g_RoadMorphTraceHavePrevious = true;
        Logger::Success(
            "18L-BV road Morph path trace armed | carX=" +
            std::to_string(carLocation.X) +
            " | carY=" + std::to_string(carLocation.Y) +
            " | landingX=" + std::to_string(landing.X) +
            " | landingY=" + std::to_string(landing.Y) +
            " | headingX=" + std::to_string(travelDirection.X) +
            " | headingY=" + std::to_string(travelDirection.Y));
    }

    void SampleRoadMorphTrace(
        AActor* car,
        const FVector& carLocation,
        ULONGLONG now)
    {
        if (!g_RoadMorphTraceCar || car != g_RoadMorphTraceCar ||
            g_RoadMorphTraceReported)
        {
            return;
        }
        if (now > g_RoadMorphTraceStartedAt + 30000)
        {
            FinishRoadMorphTrace("sample-timeout");
            return;
        }
        if (!g_RoadMorphTraceHavePrevious)
        {
            g_RoadMorphTracePreviousCar = carLocation;
            g_RoadMorphTraceHavePrevious = true;
            return;
        }

        const float segmentX = carLocation.X - g_RoadMorphTracePreviousCar.X;
        const float segmentY = carLocation.Y - g_RoadMorphTracePreviousCar.Y;
        const float lengthSquared = segmentX * segmentX +
            segmentY * segmentY;
        if (!std::isfinite(lengthSquared) ||
            lengthSquared < 50.0f * 50.0f ||
            lengthSquared > 3000.0f * 3000.0f)
        {
            g_RoadMorphTracePreviousCar = carLocation;
            return;
        }
        const float fromPreviousX = g_RoadMorphTraceLanding.X -
            g_RoadMorphTracePreviousCar.X;
        const float fromPreviousY = g_RoadMorphTraceLanding.Y -
            g_RoadMorphTracePreviousCar.Y;
        const float projection =
            (fromPreviousX * segmentX + fromPreviousY * segmentY) /
            lengthSquared;
        const float fraction = (std::max)(0.0f,
            (std::min)(1.0f, projection));
        const float offsetX = fromPreviousX - fraction * segmentX;
        const float offsetY = fromPreviousY - fraction * segmentY;
        const float distance = std::sqrt(offsetX * offsetX +
            offsetY * offsetY);
        if (std::isfinite(distance))
        {
            ++g_RoadMorphTraceSegments;
            if (distance < g_RoadMorphTraceBestDistance)
            {
                g_RoadMorphTraceBestDistance = distance;
                g_RoadMorphTraceSignedOffset =
                    (segmentX * offsetY - segmentY * offsetX) /
                    std::sqrt(lengthSquared);
            }
            // Report only when the driven center path actually runs near the
            // landing, not merely because a far-away segment projects toward
            // it. The screenshot can then confirm road edges visually.
            if (projection >= 0.0f && projection <= 1.0f &&
                distance <= 1200.0f)
            {
                g_RoadMorphTraceReported = true;
                Logger::Success(
                    "18L-BV road Morph measured against driven car center | signedLateralCm=" +
                    std::to_string(g_RoadMorphTraceSignedOffset) +
                    " | nearestCarPathCm=" +
                    std::to_string(g_RoadMorphTraceBestDistance) +
                    " | segmentCm=" +
                    std::to_string(std::sqrt(lengthSquared)) +
                    " | carX=" + std::to_string(carLocation.X) +
                    " | carY=" + std::to_string(carLocation.Y));
            }
        }
        g_RoadMorphTracePreviousCar = carLocation;
    }

